package fixture

import "testing"

func TestMax(t *testing.T) {
	if got := Max([]int{3, 1, 4, 1, 5}); got != 5 {
		t.Fatalf("Max = %d, want 5", got)
	}
	if got := Max(nil); got != 0 {
		t.Fatalf("Max(nil) = %d, want 0", got)
	}
}
